xml.Script:
        clRed    := 'C80000';
        clGreen  := '009600';
        clBlue   := '0000C8';
        clYellow := 'FFFF00';
        clWhite  := 'FFFFFF';

        H := 0.5;
        R := H;

        D := R * 0.85;

        for i := 0 to 3 do begin
            ax[i] := cos(2 * Pi / 3 * i);
            ay[i] := sin(2 * Pi / 3 * i);
        end;

        N := 60;
        for i := 0 to N - 1 do begin
            x[i] := R * cos(2 * Pi / N * i);
            y[i] := R * sin(2 * Pi / N * i);
        end;

        function FromTo(iFrom, iTo);
        begin
            Result := IntToStr(iFrom);
            for i := iFrom + 1 to iTo do
                Result := Result + ';' + IntToStr(i);
            for i := iFrom - 1 downto iTo do
                Result := Result + ';' + IntToStr(i);
        end;

Macro.Script:
i1 := i mod N;
i2 := (i + 1) mod N;
Inc(i);
